<script setup>
import { computed, ref } from 'vue';
import { Link, router, useForm, usePage } from '@inertiajs/vue3';
import AssessmentLayout from './AssessmentLayout.vue';
import { confirmAction } from './confirmAction.js';
const props=defineProps({creation:Object,finalReview:Object,peerReviews:Array,publicationLogs:Array,myReview:Object,rubric:Object,permissions:Object,assignmentOptions:Object});
const page=usePage();
const assignment=useForm({assigned_reviewer_id:props.creation.assigned_reviewer_id || null,assigned_rubric_id:props.creation.assigned_rubric_id || null,is_open_for_review:!!props.creation.is_open_for_review});
const saveAssignment=()=>assignment.patch(route('admin.creations.assignment.update',props.creation.slug));
const selectedLevels=ref({...props.myReview?.selected_levels}); const verdict=ref(props.myReview?.status || 'approved'); const feedback=ref(props.myReview?.feedback || '');
const score=computed(()=>{const max=Math.max(0,...(props.rubric?.levels || []).map(l=>Number(l.score_value)));const total=(props.rubric?.criteria || []).reduce((sum,c)=>{const level=(props.rubric?.levels || []).find(l=>l.id===Number(selectedLevels.value[c.id]));return sum+(max>0?Number(level?.score_value || 0)/max*Number(c.weight):0);},0);const weight=(props.rubric?.criteria || []).reduce((sum,c)=>sum+Number(c.weight),0);return weight>0?Math.round(total/weight*100):0;});
const submitReview=()=>router.post(route('admin.creations.review.submit',props.creation.slug),{status:verdict.value,feedback:feedback.value,selected_levels:selectedLevels.value});
const publishPeer=async review=>{if(await confirmAction('Publikasikan review ini sebagai hasil resmi?'))router.post(route('admin.creations.review.publish',{creation:props.creation.slug,peerReview:review.id}));};
const publishAggregate=async ()=>{if(await confirmAction('Publikasikan agregasi review sebagai hasil resmi?'))router.post(route('admin.creations.review.publish-aggregate',props.creation.slug));};
</script>
<template><AssessmentLayout title="Review karya" :subtitle="`${creation.title} / ${creation.creator?.name || 'Kreator'}`" breadcrumb="Komunitas & pengguna"><div class="layout"><section class="panel"><h2>{{ creation.title }}</h2><p class="muted">{{ creation.creator?.name }} / {{ creation.category }} / {{ creation.review_status }}</p><div v-if="creation.photos?.length" class="photo-grid"><img v-for="photo in creation.photos" :key="photo.id" :src="photo.url" :alt="creation.title" /></div><p>{{ creation.description }}</p><div v-if="creation.content" class="content-text">{{ creation.content }}</div><a v-if="creation.link" class="secondary" :href="creation.link" target="_blank" rel="noopener">Buka demo ↗</a><p class="muted">{{ creation.is_open_for_review ? 'Terbuka untuk review' : 'Belum terbuka untuk review' }}</p></section><aside><form v-if="permissions?.can_assign" class="panel side-panel" @submit.prevent="saveAssignment"><h2>Penugasan review</h2><label>Assigned reviewer<select v-model="assignment.assigned_reviewer_id"><option :value="null">Belum ditugaskan</option><option v-for="reviewer in assignmentOptions?.reviewers || []" :key="reviewer.id" :value="reviewer.id">{{ reviewer.name }}</option></select></label><label>Assigned rubric<select v-model="assignment.assigned_rubric_id"><option :value="null">Belum dipilih</option><option v-for="item in assignmentOptions?.rubrics || []" :key="item.id" :value="item.id" :disabled="item.is_archived">{{ item.title }}</option></select></label><label class="check"><input v-model="assignment.is_open_for_review" type="checkbox" /> Buka untuk mentor review</label><p v-if="Object.keys(assignment.errors).length" class="error">{{ Object.values(assignment.errors).join(' · ') }}</p><button class="primary" :disabled="assignment.processing">Simpan penugasan</button></form><form v-if="permissions?.can_review && rubric" class="panel side-panel" @submit.prevent="submitReview"><h2>Academic evaluation</h2><p class="muted">{{ rubric.rubric?.title }} · Perkiraan skor {{ score }}%</p><label v-for="criterion in rubric.criteria || []" :key="criterion.id">{{ criterion.name }} · {{ criterion.weight }}%<select v-model="selectedLevels[criterion.id]" required><option :value="null">Pilih level</option><option v-for="level in rubric.levels || []" :key="level.id" :value="level.id">{{ level.label }} · {{ level.score_value }}</option></select></label><label>Verdict status<select v-model="verdict"><option value="approved">Disetujui</option><option value="needs_revision">Perlu revisi</option></select></label><label>Reviewer feedback<textarea v-model="feedback" rows="4" /></label><p v-if="Object.keys(page.props.errors || {}).length" class="error">{{ Object.values(page.props.errors).join(' · ') }}</p><button class="primary">Submit review</button></form><section v-if="finalReview" class="panel"><h2>Hasil resmi</h2><p>{{ finalReview.status }} · {{ finalReview.score_percent }}%</p><p class="muted">{{ finalReview.feedback }}</p></section></aside></div><section class="panel history"><h2>Publication history &amp; peer reviews</h2><div v-for="review in peerReviews || []" :key="review.id" class="review-row"><div><strong>{{ review.reviewer_label || review.reviewer_name || 'Reviewer' }}</strong><p class="muted">{{ review.status }} · {{ review.score_percent }}% · {{ review.feedback }}</p></div><button v-if="permissions?.can_publish_official" class="secondary" type="button" @click="publishPeer(review)">Publikasikan</button></div><button v-if="permissions?.can_publish_aggregate && peerReviews?.length > 1" class="primary" type="button" @click="publishAggregate">Publikasikan agregasi</button><p v-if="!peerReviews?.length" class="muted">Belum ada review.</p><p v-for="log in publicationLogs || []" :key="log.id" class="muted">{{ log.created_at || log.published_at }} · {{ log.publisher_name || 'Publikasi' }}</p></section><div class="actions"><Link class="secondary" :href="route('redesign.creations.queue',{review_status:'all'})">← Antrian review</Link></div></AssessmentLayout></template>
<style scoped>.photo-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:20px 0}.photo-grid img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:8px}.content-text{white-space:pre-wrap;font-size:13px;margin:20px 0}.side-panel{display:grid;gap:15px;margin-bottom:18px}.side-panel label{display:grid;gap:7px;font-size:12px;font-weight:700}.side-panel label.check{display:flex;align-items:center}.check input{width:auto}.side-panel :is(input,select,textarea){border:1px solid #dce6e8;padding:10px;border-radius:8px;background:#fff}.side-panel button{justify-self:start}.history{margin-top:20px}.review-row{display:flex;justify-content:space-between;gap:12px;border-top:1px solid #e5edef;padding:16px 0}.review-row strong{font-size:13px}</style>
